var asm = Assembly.LoadFrom("/home/runner/.nuget/packages/microsoft.agents.ai/1.11.1/lib/net10.0/Microsoft.Agents.AI.dll");

var agentType = asm.GetType("Microsoft.Agents.AI.ChatClientAgent")!;
Console.WriteLine("=== Constructors ===");
foreach (var c in agentType.GetConstructors())
{
    var ps = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  ({ps})");
}

Console.WriteLine("\n=== Public Properties ===");
foreach (var p in agentType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {{ {(p.CanRead?"get;":"")} {(p.CanWrite?"set;":"")} }}");

Console.WriteLine("\n=== Public Methods (declared) ===");
foreach (var m in agentType.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly))
    Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");

// Also check options types
foreach (var name in new[] { "ChatClientAgentOptions", "ChatClientAgentRunOptions" })
{
    var t = asm.GetType($"Microsoft.Agents.AI.{name}");
    if (t == null) continue;
    Console.WriteLine($"\n=== {name} Properties ===");
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {{ {(p.CanRead?"get;":"")} {(p.CanWrite?"set;":"")} }}");
}

// Check base Agent class
var baseType = agentType.BaseType!;
Console.WriteLine($"\n=== Base: {baseType.FullName} ===");
foreach (var m in baseType.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
    Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
foreach (var p in baseType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name} {{ {(p.CanRead?"get;":"")} {(p.CanWrite?"set;":"")} }}");
EOF
