using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Instantiate the tools ---
var researchTools = new ResearchTools();

IList<AITool> tools =
[
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
];

// --- Create the agent ---
var instructions = """
    You are a research agent. Your job is to research a topic thoroughly by
    searching the web, saving important findings as notes, and then producing
    a clear summary.

    Workflow:
    1. Search the web for the given topic using different relevant queries.
    2. Save key findings as notes using the SaveNote tool.
    3. Retrieve all your notes with GetNotes to review what you've gathered.
    4. Produce a final, well-structured summary of your research.

    Always search at least 2-3 different queries to get broad coverage.
    Always save at least 3 notes before summarizing.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and summarizing findings",
    tools: tools);

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
using var cts = new CancellationTokenSource(TimeSpan.FromMinutes(3));
var session = await agent.CreateSessionAsync(cancellationToken: cts.Token);

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    cancellationToken: cts.Token))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();

// =========================================================================
// Tool definitions
// =========================================================================

public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<string> _notes = [];

    [Description("Searches the web for a query and returns a list of result snippets. Use this to find information about a topic.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            using var response = await s_httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html);

            return results.Count > 0
                ? JsonSerializer.Serialize(results)
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Saves a research note. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A concise title for the note")] string title,
        [Description("The content of the note with key findings")] string content)
    {
        var note = $"[{title}]: {content}";
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes. Use this to review gathered findings before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet. Use SaveNote to record findings first.";
        }

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"{i + 1}. {_notes[i]}");
        }

        return sb.ToString();
    }

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        var snippetMarker = "result__snippet";
        var titleMarker = "result__a";
        var index = 0;

        while (results.Count < 5)
        {
            var titlePos = html.IndexOf(titleMarker, index, StringComparison.Ordinal);
            if (titlePos < 0) break;

            var titleText = ExtractTagContent(html, titlePos);

            var snippetPos = html.IndexOf(snippetMarker, titlePos, StringComparison.Ordinal);
            if (snippetPos < 0) break;

            var snippetText = ExtractTagContent(html, snippetPos);
            index = snippetPos + 1;

            if (!string.IsNullOrWhiteSpace(titleText) && !string.IsNullOrWhiteSpace(snippetText))
            {
                results.Add(new SearchResult(
                    CleanHtml(titleText),
                    CleanHtml(snippetText)));
            }
        }

        return results;
    }

    private static string ExtractTagContent(string html, int markerPos)
    {
        var tagClose = html.IndexOf('>', markerPos);
        if (tagClose < 0) return string.Empty;

        var contentStart = tagClose + 1;
        var contentEnd = html.IndexOf('<', contentStart);
        if (contentEnd < 0) return string.Empty;

        var content = html[contentStart..contentEnd];
        if (content.Length < 10)
        {
            var extendedEnd = html.IndexOf("</", contentStart, StringComparison.Ordinal);
            if (extendedEnd > 0)
            {
                content = html[contentStart..extendedEnd];
            }
        }

        return content.Trim();
    }

    private static string CleanHtml(string text)
    {
        var cleaned = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", " ");
        cleaned = WebUtility.HtmlDecode(cleaned);
        return System.Text.RegularExpressions.Regex.Replace(cleaned, @"\s+", " ").Trim();
    }
}

public record SearchResult(string Title, string Snippet);

